{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "overview_title",
        "hero_image",
        "overview_description",
        "movie_selection_title",
        "movie_comparison_table",
        "curated_films_section",
        "marathon_schedule_title",
        "marathon_schedule_table",
        "quick_actions_title",
        "quick_actions_stack",
        "sources_title",
        "sources_stack"
      ]
    },
    "overview_title": {
      "type": "Text",
      "props": {
        "text": "90s Sci-Fi Adventure Marathon Overview",
        "variant": "h1"
      },
      "children": []
    },
    "hero_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Andromeda_Galaxy_%28with_h-alpha%29.jpg/1200px-Andromeda_Galaxy_%28with_h-alpha%29.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "overview_description": {
      "type": "Text",
      "props": {
        "text": "This family-friendly marathon focuses on the wonder of space and time. We have selected three films rated PG or PG-13 that avoid dark dystopian themes, ensuring an uplifting experience for all ages.",
        "variant": "body"
      },
      "children": []
    },
    "movie_selection_title": {
      "type": "Text",
      "props": {
        "text": "Movie Selection and Comparison",
        "variant": "h1"
      },
      "children": []
    },
    "movie_comparison_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "title",
            "label": "Movie Title"
          },
          {
            "key": "year",
            "label": "Year"
          },
          {
            "key": "runtime",
            "label": "Runtime"
          },
          {
            "key": "rating",
            "label": "Rating"
          }
        ],
        "rows": [
          {
            "title": "Galaxy Quest",
            "year": "1999",
            "runtime": "102 mins",
            "rating": "PG"
          },
          {
            "title": "Men in Black",
            "year": "1997",
            "runtime": "98 mins",
            "rating": "PG-13"
          },
          {
            "title": "Space Jam",
            "year": "1996",
            "runtime": "88 mins",
            "rating": "PG"
          },
          {
            "title": "Stargate",
            "year": "1994",
            "runtime": "121 mins",
            "rating": "PG-13"
          },
          {
            "title": "Back to the Future Part III",
            "year": "1990",
            "runtime": "118 mins",
            "rating": "PG"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "title",
        "highlightColumns": [
          "rating",
          "runtime"
        ]
      },
      "children": []
    },
    "curated_films_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "curated_films_title_stack",
        "galaxy_quest_card",
        "mib_card",
        "space_jam_card"
      ]
    },
    "curated_films_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "curated_films_icon",
        "curated_films_text"
      ]
    },
    "curated_films_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/ticket-perforated.svg"
      },
      "children": []
    },
    "curated_films_text": {
      "type": "Text",
      "props": {
        "text": "Curated Film Selections",
        "variant": "h2"
      },
      "children": []
    },
    "galaxy_quest_card": {
      "type": "Card",
      "props": {},
      "children": [
        "galaxy_quest_title",
        "galaxy_quest_description"
      ]
    },
    "galaxy_quest_title": {
      "type": "Text",
      "props": {
        "text": "Galaxy Quest (1999)",
        "variant": "h3"
      },
      "children": []
    },
    "galaxy_quest_description": {
      "type": "Text",
      "props": {
        "text": "The cast of a defunct sci-fi series is abducted by actual aliens who believe the show is a historical record. It is a perfect tribute to space exploration fandom.",
        "variant": "body"
      },
      "children": []
    },
    "mib_card": {
      "type": "Card",
      "props": {},
      "children": [
        "mib_title",
        "mib_description"
      ]
    },
    "mib_title": {
      "type": "Text",
      "props": {
        "text": "Men in Black (1997)",
        "variant": "h3"
      },
      "children": []
    },
    "mib_description": {
      "type": "Text",
      "props": {
        "text": "A secret agency polices extraterrestrial populations on Earth to keep their presence hidden from the public. It offers a comedic and friendly look at alien contact.",
        "variant": "body"
      },
      "children": []
    },
    "space_jam_card": {
      "type": "Card",
      "props": {},
      "children": [
        "space_jam_title",
        "space_jam_description"
      ]
    },
    "space_jam_title": {
      "type": "Text",
      "props": {
        "text": "Space Jam (1996)",
        "variant": "h3"
      },
      "children": []
    },
    "space_jam_description": {
      "type": "Text",
      "props": {
        "text": "NBA legend Michael Jordan teams up with Looney Tunes characters to win a high-stakes basketball game against alien invaders. It is an iconic 90s crossover that fits the friendly alien theme.",
        "variant": "body"
      },
      "children": []
    },
    "marathon_schedule_title": {
      "type": "Text",
      "props": {
        "text": "Marathon Schedule (18:00 - 23:18)",
        "variant": "h1"
      },
      "children": []
    },
    "marathon_schedule_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "event",
            "label": "Event"
          },
          {
            "key": "snack",
            "label": "Snack"
          }
        ],
        "rows": [
          {
            "time": "18:00",
            "event": "Galaxy Quest",
            "snack": "\"Thermian\" green gelatin cubes."
          },
          {
            "time": "19:42",
            "event": "Break 1",
            "snack": "15-minute intermission."
          },
          {
            "time": "19:57",
            "event": "Men in Black",
            "snack": "\"Neuralyzer\" silver-wrapped licorice sticks."
          },
          {
            "time": "21:35",
            "event": "Break 2",
            "snack": "15-minute intermission."
          },
          {
            "time": "21:50",
            "event": "Space Jam",
            "snack": "\"Secret Stuff\" lemon-lime sports drink."
          },
          {
            "time": "23:18",
            "event": "Conclusion",
            "snack": ""
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "time",
        "highlightColumns": [
          "event"
        ]
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h1"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "imdb_button",
        "justwatch_button"
      ]
    },
    "imdb_button": {
      "type": "Button",
      "props": {
        "label": "View IMDb Details"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.imdb.com"
          }
        }
      },
      "children": []
    },
    "justwatch_button": {
      "type": "Button",
      "props": {
        "label": "Find Streaming Options"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.justwatch.com"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h1"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_text"
      ]
    },
    "source_text": {
      "type": "Text",
      "props": {
        "text": "Movie data from IMDb and JustWatch. Marathon concept by GenUICraft.",
        "variant": "caption"
      },
      "children": []
    }
  }
}
